if ( ! in_array( 'woocommerce/woocommerce.php', apply_filters( 'active_plugins', get_option( 'active_plugins' ) ) ) ) {
    return;
}

// Add new category
function wc_new_product_categories_add_category() {
    register_taxonomy(
        'product_new', // Taxonomy
        'product', // Base
        'New Products', // Label
        'https://example.com/new-products', // Register
        array(
            'hierarchical' => true,
            'rewrite' => array('slug' => 'new-products'),
        )
    );
}
add_action( 'init', 'wc_new_product_categories_add_category' );

// Add new products to new products category
