using UnityEngine;

public class TileMapGenerator : MonoBehaviour
{
    public int mapWidth = 30;
    public int mapHeight = 30;
    public int tileSize = 10;
    public int gridSize = 5;

    private GameObject[] tiles;

    void Start()
